package org.mtr.mapping.holder;import org.mtr.mapping.annotation.MappedMethod;import org.mtr.mapping.tool.HolderBase;import javax.annotation.Nonnull;import javax.annotation.Nullable;import javax.annotation.ParametersAreNonnullByDefault;@ParametersAreNonnullByDefault@SuppressWarnings({"deprecation","unchecked","unused"})public enum LightType{SKY(net.minecraft.world.level.LightLayer.SKY),BLOCK(net.minecraft.world.level.LightLayer.BLOCK);public final net.minecraft.world.level.LightLayer data;LightType(net.minecraft.world.level.LightLayer data){this.data=data;}public static LightType convert(@Nullable net.minecraft.world.level.LightLayer data){return data==null?null:values()[data.ordinal()];}@MappedMethod public final boolean equals(@Nullable LightType data){return data!=null&&this.data==data.data;}@Nonnull@MappedMethod public static LightType getBlockMapped(){return LightType.convert(net.minecraft.world.level.LightLayer.BLOCK);}@Nonnull@MappedMethod public static LightType getSkyMapped(){return LightType.convert(net.minecraft.world.level.LightLayer.SKY);}}